### 1. `BookQuote.swift` — цитата в том виде, в каком её видят экраны

```swift
import Foundation

/// Цитата из книги в том виде, в каком её видят экраны.
/// Не зависит от способа хранения: SwiftData сейчас, GRDB потом.
struct BookQuote: Identifiable, Hashable, Sendable {
    let id: UUID
    let text: String
    let bookID: UUID
    let createdAt: Date
}

enum QuoteStoreError: Error, Equatable {
    /// Текст пустой или состоит только из пробелов и переносов строк.
    case emptyText
}

extension BookQuote {
    /// Готовит новую цитату: убирает пробелы и переносы по краям, пустой текст не принимает.
    /// Общее правило для всех хранилищ, чтобы они не разошлись.
    static func new(text: String, bookID: UUID, createdAt: Date) throws -> BookQuote {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { throw QuoteStoreError.emptyText }
        return BookQuote(id: UUID(), text: trimmed, bookID: bookID, createdAt: createdAt)
    }
}
```

### 2. `QuoteStore.swift` — договор между экранами и хранилищем

```swift
import Foundation

/// Хранилище цитат. Экраны работают только с ним и не знают, где лежат данные.
///
/// Договор, одинаковый для любой реализации:
/// - список книги отсортирован от новых к старым; порядок цитат с одинаковым временем не задан;
/// - `addQuote` убирает пробелы по краям и бросает `QuoteStoreError.emptyText` на пустой текст;
/// - `deleteQuote` для несуществующей цитаты ничего не делает и не бросает ошибку;
/// - `observeQuotes` сразу отдаёт текущий список, затем новый список после каждого
///   добавления или удаления в этой книге.
///
/// На всё приложение создаётся одно хранилище: подписчики узнают только об изменениях,
/// прошедших через тот же экземпляр.
protocol QuoteStore: Sendable {
    func quotes(ofBook bookID: UUID) async throws -> [BookQuote]
    func observeQuotes(ofBook bookID: UUID) async -> AsyncThrowingStream<[BookQuote], any Error>
    @discardableResult
    func addQuote(text: String, toBook bookID: UUID) async throws -> BookQuote
    func deleteQuote(id: UUID) async throws
}

/// Подписчики на списки цитат. Хранится внутри актора хранилища и вызывается только из него.
struct QuoteObservers {
    typealias Stream = AsyncThrowingStream<[BookQuote], any Error>

    private var entries: [UUID: (bookID: UUID, continuation: Stream.Continuation)] = [:]

    /// Регистрирует подписчика. Когда экран перестаёт слушать, `onTermination`
    /// получает токен, который надо передать в `remove`.
    mutating func add(bookID: UUID, onTermination: @escaping @Sendable (UUID) -> Void) -> Stream {
        // Экрану нужен только последний список, промежуточные можно пропустить.
        let (stream, continuation) = Stream.makeStream(bufferingPolicy: .bufferingNewest(1))
        let token = UUID()
        entries[token] = (bookID, continuation)
        continuation.onTermination = { _ in onTermination(token) }
        return stream
    }

    mutating func remove(_ token: UUID) {
        entries[token] = nil
    }

    /// Отправляет свежий список всем подписчикам книги. Если прочитать список не удалось,
    /// их потоки завершаются с этой ошибкой.
    func publish(bookID: UUID, fetch: () throws -> [BookQuote]) {
        let targets = entries.values.filter { $0.bookID == bookID }.map(\.continuation)
        guard !targets.isEmpty else { return }
        do {
            let list = try fetch()
            targets.forEach { $0.yield(list) }
        } catch {
            targets.forEach { $0.finish(throwing: error) }
        }
    }
}
```

### 3. `SwiftDataQuoteStore.swift` — нынешняя реализация на SwiftData

```swift
import Foundation
import SwiftData

// Ожидаемый вид существующей модели (её не меняем):
//
// @Model final class Quote {
//     var id: UUID
//     var text: String
//     var bookID: UUID
//     var createdAt: Date
//     init(id: UUID, text: String, bookID: UUID, createdAt: Date) { ... }
// }

/// Хранилище цитат на SwiftData. Единственное место, где цитаты связаны со SwiftData.
struct SwiftDataQuoteStore: QuoteStore {
    private let database: Task<QuoteDatabase, Never>
    private let now: @Sendable () -> Date

    init(modelContainer: ModelContainer, now: @escaping @Sendable () -> Date = { Date() }) {
        // Актор создаётся вне главного потока: если создать его на главном,
        // SwiftData выполняет всю его работу там же, и интерфейс подтормаживает.
        database = Task.detached { QuoteDatabase(modelContainer: modelContainer) }
        self.now = now
    }

    func quotes(ofBook bookID: UUID) async throws -> [BookQuote] {
        try await database.value.quotes(ofBook: bookID)
    }

    func observeQuotes(ofBook bookID: UUID) async -> AsyncThrowingStream<[BookQuote], any Error> {
        await database.value.observeQuotes(ofBook: bookID)
    }

    @discardableResult
    func addQuote(text: String, toBook bookID: UUID) async throws -> BookQuote {
        let quote = try BookQuote.new(text: text, bookID: bookID, createdAt: now())
        try await database.value.insert(quote)
        return quote
    }

    func deleteQuote(id: UUID) async throws {
        try await database.value.delete(id: id)
    }
}

/// Вся работа со SwiftData идёт через этот актор: по одной операции, вне главного потока.
@ModelActor
actor QuoteDatabase {
    private var observers = QuoteObservers()

    func quotes(ofBook bookID: UUID) throws -> [BookQuote] {
        let descriptor = FetchDescriptor<Quote>(
            predicate: #Predicate { $0.bookID == bookID },
            sortBy: [SortDescriptor(\.createdAt, order: .reverse)]
        )
        return try modelContext.fetch(descriptor).map(BookQuote.init)
    }

    func observeQuotes(ofBook bookID: UUID) -> AsyncThrowingStream<[BookQuote], any Error> {
        let stream = observers.add(bookID: bookID) { token in
            Task { await self.removeObserver(token) }
        }
        observers.publish(bookID: bookID) { try quotes(ofBook: bookID) }
        return stream
    }

    func insert(_ quote: BookQuote) throws {
        modelContext.insert(
            Quote(id: quote.id, text: quote.text, bookID: quote.bookID, createdAt: quote.createdAt)
        )
        try saveOrRollback()
        observers.publish(bookID: quote.bookID) { try quotes(ofBook: quote.bookID) }
    }

    func delete(id: UUID) throws {
        let targetID = id
        let matches = try modelContext.fetch(
            FetchDescriptor<Quote>(predicate: #Predicate { $0.id == targetID })
        )
        guard !matches.isEmpty else { return }
        let affectedBooks = Set(matches.map(\.bookID))
        for match in matches {
            modelContext.delete(match)
        }
        try saveOrRollback()
        for bookID in affectedBooks {
            observers.publish(bookID: bookID) { try quotes(ofBook: bookID) }
        }
    }

    private func removeObserver(_ token: UUID) {
        observers.remove(token)
    }

    /// Если сохранить не удалось, несохранённое изменение отменяется, чтобы оно
    /// не записалось потом вместе с чужим сохранением.
    private func saveOrRollback() throws {
        do {
            try modelContext.save()
        } catch {
            modelContext.rollback()
            throw error
        }
    }
}

extension BookQuote {
    init(_ model: Quote) {
        self.init(id: model.id, text: model.text, bookID: model.bookID, createdAt: model.createdAt)
    }
}
```

### 4. `InMemoryQuoteStore.swift` — хранилище в памяти для превью SwiftUI и тестов

```swift
import Foundation

/// Хранилище в памяти: для превью SwiftUI и тестов. Ведёт себя по тому же договору, что и настоящее.
actor InMemoryQuoteStore: QuoteStore {
    private var all: [BookQuote]
    private var observers = QuoteObservers()
    private let now: @Sendable () -> Date

    init(quotes: [BookQuote] = [], now: @escaping @Sendable () -> Date = { Date() }) {
        self.all = quotes
        self.now = now
    }

    func quotes(ofBook bookID: UUID) -> [BookQuote] {
        all.filter { $0.bookID == bookID }.sorted { $0.createdAt > $1.createdAt }
    }

    func observeQuotes(ofBook bookID: UUID) -> AsyncThrowingStream<[BookQuote], any Error> {
        let stream = observers.add(bookID: bookID) { token in
            Task { await self.removeObserver(token) }
        }
        observers.publish(bookID: bookID) { quotes(ofBook: bookID) }
        return stream
    }

    @discardableResult
    func addQuote(text: String, toBook bookID: UUID) throws -> BookQuote {
        let quote = try BookQuote.new(text: text, bookID: bookID, createdAt: now())
        all.append(quote)
        observers.publish(bookID: bookID) { quotes(ofBook: bookID) }
        return quote
    }

    func deleteQuote(id: UUID) {
        let affectedBooks = Set(all.filter { $0.id == id }.map(\.bookID))
        all.removeAll { $0.id == id }
        for bookID in affectedBooks {
            observers.publish(bookID: bookID) { quotes(ofBook: bookID) }
        }
    }

    private func removeObserver(_ token: UUID) {
        observers.remove(token)
    }
}
```

### 5. `BookQuotesView.swift` — пример экрана и подключение

```swift
import SwiftUI

@MainActor
@Observable
final class BookQuotesModel {
    private(set) var quotes: [BookQuote] = []
    private(set) var isAdding = false
    var errorMessage: String?

    private let bookID: UUID
    private let store: any QuoteStore

    init(bookID: UUID, store: any QuoteStore) {
        self.bookID = bookID
        self.store = store
    }

    /// Держит список актуальным, пока экран открыт. Вызывается из `.task`:
    /// когда экран закрывается, подписка снимается сама.
    func observe() async {
        let updates = await store.observeQuotes(ofBook: bookID)
        do {
            for try await list in updates {
                quotes = list
            }
        } catch {
            errorMessage = "Не удалось загрузить цитаты."
        }
    }

    /// Возвращает `true`, если цитата сохранена и поле ввода можно очистить.
    func add(_ text: String) async -> Bool {
        guard !isAdding else { return false }
        isAdding = true
        defer { isAdding = false }
        do {
            try await store.addQuote(text: text, toBook: bookID)
            return true
        } catch QuoteStoreError.emptyText {
            return false
        } catch {
            errorMessage = "Не удалось сохранить цитату. Попробуйте ещё раз."
            return false
        }
    }

    func delete(_ quote: BookQuote) async {
        // Строка исчезает сразу, не дожидаясь хранилища, чтобы анимация удаления была плавной.
        quotes.removeAll { $0.id == quote.id }
        do {
            try await store.deleteQuote(id: quote.id)
        } catch {
            errorMessage = "Не удалось удалить цитату."
            if let fresh = try? await store.quotes(ofBook: bookID) {
                quotes = fresh
            }
        }
    }
}

struct BookQuotesView: View {
    @State private var model: BookQuotesModel
    @State private var draft = ""

    init(bookID: UUID, store: any QuoteStore) {
        _model = State(initialValue: BookQuotesModel(bookID: bookID, store: store))
    }

    var body: some View {
        List {
            Section {
                TextField("Новая цитата", text: $draft, axis: .vertical)
                Button("Добавить") {
                    Task {
                        if await model.add(draft) { draft = "" }
                    }
                }
                .disabled(model.isAdding || draft.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
            }
            Section {
                ForEach(model.quotes) { quote in
                    Text(quote.text)
                }
                .onDelete { offsets in
                    let doomed = offsets.map { model.quotes[$0] }
                    Task {
                        for quote in doomed { await model.delete(quote) }
                    }
                }
            }
        }
        .task { await model.observe() }
        .alert(
            "Что-то пошло не так",
            isPresented: Binding(
                get: { model.errorMessage != nil },
                set: { if !$0 { model.errorMessage = nil } }
            )
        ) {
            Button("OK", role: .cancel) {}
        } message: {
            Text(model.errorMessage ?? "")
        }
    }
}

