// SlumpyCore/BookQuote.swift
import Foundation

/// A quote as screens see it: plain value, independent of the storage engine.
public struct BookQuote: Identifiable, Hashable, Sendable {
    public let id: UUID
    public let bookID: UUID
    public let text: String
    public let createdAt: Date

    public init(id: UUID, bookID: UUID, text: String, createdAt: Date) {
        self.id = id
        self.bookID = bookID
        self.text = text
        self.createdAt = createdAt
    }
}

public enum QuoteError: Error, Equatable, Sendable {
    case emptyText
}

extension BookQuote {
    /// A new quote ready to be saved. Leading and trailing whitespace is dropped; empty text is rejected.
    public static func new(text: String, bookID: UUID, now: Date = .now) throws -> BookQuote {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.isEmpty else { throw QuoteError.emptyText }
        return BookQuote(id: UUID(), bookID: bookID, text: trimmed, createdAt: now)
    }
}
