// SlumpyCore/QuoteStore.swift
import Foundation

/// Storage of quotes. Screens depend on this, never on a concrete engine.
public protocol QuoteStore: Sendable {
    /// Quotes of the book, newest first.
    func quotes(ofBook bookID: UUID) async throws -> [BookQuote]
    /// Saves a quote made by `BookQuote.new`.
    func add(_ quote: BookQuote) async throws
    /// Deletes the quote. Deleting a quote that is already gone does nothing.
    func delete(quoteID: UUID) async throws
}
```

