## 4. Реализация на SwiftData

```swift
// Slumpy/Storage/SwiftDataQuoteStore.swift
import Foundation
import SwiftData
import SlumpyCore

/// The only place that knows quotes live in SwiftData.
/// SwiftData objects never leave this actor; callers get `BookQuote` values.
@ModelActor
actor SwiftDataQuoteStore: QuoteStore {
    func quotes(ofBook bookID: UUID) throws -> [BookQuote] {
        let descriptor = FetchDescriptor<Quote>(
            predicate: #Predicate<Quote> { $0.bookID == bookID },
            sortBy: [SortDescriptor(\.createdAt, order: .reverse)]
        )
        return try modelContext.fetch(descriptor).map {
            BookQuote(id: $0.id, bookID: $0.bookID, text: $0.text, createdAt: $0.createdAt)
        }
    }

    func add(_ quote: BookQuote) throws {
        modelContext.insert(
            Quote(id: quote.id, text: quote.text, bookID: quote.bookID, createdAt: quote.createdAt)
        )
        try saveOrRollback()
    }

    func delete(quoteID: UUID) throws {
        let descriptor = FetchDescriptor<Quote>(predicate: #Predicate<Quote> { $0.id == quoteID })
        for quote in try modelContext.fetch(descriptor) {
            modelContext.delete(quote)
        }
        try saveOrRollback()
    }

    /// A failed save must not leave the change pending, or a later save would apply it.
    private func saveOrRollback() throws {
        do {
            try modelContext.save()
        } catch {
            modelContext.rollback()
            throw error
        }
    }
}
```

