## 6. Модель экрана и пример экрана

```swift
// SlumpyCore/BookQuotesModel.swift
import Foundation
import Observation

/// State of the quote list for one book.
@MainActor
@Observable
public final class BookQuotesModel {
    public let bookID: UUID
    public private(set) var quotes: [BookQuote] = []
    public var error: (any Error)?

    @ObservationIgnored private let store: any QuoteStore
    /// Bumped by every finished add or delete, so a load that overlapped one is redone.
    @ObservationIgnored private var revision = 0

    public init(bookID: UUID, store: any QuoteStore) {
        self.bookID = bookID
        self.store = store
    }

    public func load() async {
        do {
            while true {
                let started = revision
                let fetched = try await store.quotes(ofBook: bookID)
                if started == revision {
                    quotes = fetched
                    return
                }
            }
        } catch {
            self.error = error
        }
    }

    /// Returns true when the quote was saved, so the screen can clear the input.
    @discardableResult
    public func add(text: String) async -> Bool {
        do {
            let quote = try BookQuote.new(text: text, bookID: bookID)
            try await store.add(quote)
            revision += 1
            quotes.removeAll { $0.id == quote.id }
            quotes.append(quote)
            quotes.sort { $0.createdAt > $1.createdAt }
            return true
        } catch {
            self.error = error
            return false
        }
    }

    public func delete(_ quote: BookQuote) async {
        do {
            try await store.delete(quoteID: quote.id)
            revision += 1
            quotes.removeAll { $0.id == quote.id }
        } catch {
            self.error = error
        }
    }
}
```

