## 7. Тесты

Одни и те же сценарии прогоняются на каждой реализации хранилища. Данные записываются через один экземпляр хранилища, а читаются через другой, открытый поверх тех же данных. Так тест поймает случай, когда изменение не сохранилось.

```swift
// SlumpyTests/QuoteStoreContractTests.swift
import Foundation
import SwiftData
import Testing
import SlumpyCore
@testable import Slumpy

enum StoreKind: CaseIterable, Sendable {
    case inMemory
    case swiftData
    // case grdb   ← add when GRDB arrives

    /// Returns a function that opens a fresh store over the same underlying data.
    func opener() throws -> @Sendable () -> any QuoteStore {
        switch self {
        case .inMemory:
            let store = InMemoryQuoteStore()
            return { store }
        case .swiftData:
            let container = try ModelContainer(
                for: Quote.self,
                configurations: ModelConfiguration(isStoredInMemoryOnly: true)
            )
            return { SwiftDataQuoteStore(modelContainer: container) }
        }
    }
}

struct QuoteStoreContractTests {
    let book = UUID()
    let otherBook = UUID()

    func quote(_ text: String, book: UUID, at seconds: TimeInterval) -> BookQuote {
        BookQuote(id: UUID(), bookID: book, text: text, createdAt: Date(timeIntervalSince1970: seconds))
    }

    @Test(arguments: StoreKind.allCases)
    func listsOnlyThisBookNewestFirst(kind: StoreKind) async throws {
        let open = try kind.opener()
        let writer = open()
        let old = quote("old", book: book, at: 100)
        let new = quote("new", book: book, at: 200)
        let foreign = quote("foreign", book: otherBook, at: 300)
        for item in [old, foreign, new] { try await writer.add(item) }

        #expect(try await open().quotes(ofBook: book) == [new, old])
    }

    @Test(arguments: StoreKind.allCases)
    func deleteRemovesOnlyThatQuoteAndRepeatIsHarmless(kind: StoreKind) async throws {
        let open = try kind.opener()
        let writer = open()
        let kept = quote("kept", book: book, at: 100)
        let removed = quote("removed", book: book, at: 200)
        try await writer.add(kept)
        try await writer.add(removed)

        try await writer.delete(quoteID: removed.id)
        try await writer.delete(quoteID: removed.id)

        #expect(try await open().quotes(ofBook: book) == [kept])
    }
}
